// Auto-generated binary image server for Pinterest CDN fetching
const imagesMap: Record<string, string> = {
  "pin_concrete-calculator.jpg": "",
  "pin_flooring-calculator.jpg": "",
  "pin_gravel-calculator.jpg": "",
  "pin_laminate-calculator.jpg": "",
  "pin_paint-calculator.jpg": "",
  "pin_patio-calculator.jpg": "",
  "pin_room-area-calculator.jpg": "",
  "pin_tile-calculator.jpg": ""
};

export async function GET(
  request: Request,
  { params }: { params: { name: string } }
) {
  const fileName = params.name;
  const base64Data = imagesMap[fileName];

  if (!base64Data) {
    return new Response('Image Not Found', { status: 404 });
  }

  const buffer = Buffer.from(base64Data, 'base64');

  return new Response(buffer, {
    headers: {
      'Content-Type': 'image/jpeg',
      'Access-Control-Allow-Origin': '*',
      'Cache-Control': 'public, max-age=31536000, immutable',
    },
  });
}
